package mz.bam.seeky.android;
import android.content.*;import android.database.*;import android.database.sqlite.*;import java.util.*;
/** Optional reading tools have their own database; existing study schemas remain compatible. */
final class PlusStore extends SQLiteOpenHelper {
 static final String[] TABLES={"collections","book_meta","book_collections","voice_notes","ocr_text","bible_sources","bible_verses","audio_tracks","audio_cues","workspace_state"};
 PlusStore(Context c){super(c,"seeky-plus.db",null,1);setWriteAheadLoggingEnabled(true);}
 public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE workspace_state(id INTEGER PRIMARY KEY,token TEXT NOT NULL)");d.execSQL("CREATE TABLE collections(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE)");d.execSQL("CREATE TABLE book_meta(hash TEXT PRIMARY KEY,topic TEXT NOT NULL DEFAULT '',series TEXT NOT NULL DEFAULT '')");d.execSQL("CREATE TABLE book_collections(hash TEXT NOT NULL,collection INTEGER NOT NULL,PRIMARY KEY(hash,collection))");d.execSQL("CREATE TABLE voice_notes(id INTEGER PRIMARY KEY AUTOINCREMENT,uri TEXT NOT NULL,material INTEGER NOT NULL DEFAULT 0,segment INTEGER NOT NULL,position INTEGER NOT NULL DEFAULT 0,title TEXT NOT NULL,path TEXT NOT NULL,created INTEGER NOT NULL)");d.execSQL("CREATE INDEX voice_origin ON voice_notes(uri,segment,created)");d.execSQL("CREATE TABLE ocr_text(uri TEXT NOT NULL,segment INTEGER NOT NULL,digest TEXT NOT NULL,value TEXT NOT NULL,created INTEGER NOT NULL,PRIMARY KEY(uri,segment))");d.execSQL("CREATE TABLE bible_sources(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,created INTEGER NOT NULL)");d.execSQL("CREATE TABLE bible_verses(source INTEGER NOT NULL,book TEXT NOT NULL,chapter INTEGER NOT NULL,verse INTEGER NOT NULL,value TEXT NOT NULL,PRIMARY KEY(source,book,chapter,verse))");d.execSQL("CREATE TABLE audio_tracks(id INTEGER PRIMARY KEY AUTOINCREMENT,uri TEXT NOT NULL UNIQUE,book_uri TEXT NOT NULL,title TEXT NOT NULL,duration INTEGER NOT NULL,created INTEGER NOT NULL)");d.execSQL("CREATE TABLE audio_cues(track INTEGER NOT NULL,position INTEGER NOT NULL,label TEXT NOT NULL,segment INTEGER NOT NULL,PRIMARY KEY(track,position,label))");}
 public void onUpgrade(SQLiteDatabase d,int o,int n){}
 List<StudyStore.Row> rows(String table,String where,String[] args,String order,int limit){if(!Arrays.asList(TABLES).contains(table))throw new IllegalArgumentException();List<StudyStore.Row> rows=new ArrayList<>();try(Cursor c=getReadableDatabase().query(table,null,where,args,null,null,order,""+Math.max(1,Math.min(10000,limit)))){while(c.moveToNext()){StudyStore.Row r=new StudyStore.Row();for(int i=0;i<c.getColumnCount();i++)r.put(c.getColumnName(i),c.getString(i));rows.add(r);}}return rows;}
 long save(String table,ContentValues value){if(!Arrays.asList(TABLES).contains(table))throw new IllegalArgumentException();return getWritableDatabase().insertWithOnConflict(table,null,value,SQLiteDatabase.CONFLICT_REPLACE);}
 static String hash(String hash){if(!hash.matches("[a-f0-9]{64}"))throw new IllegalArgumentException("Livro sem identidade válida.");return hash;}
 Set<String> hashes(String kind,String value){Set<String> found=new HashSet<>();String sql;String[] args={value};if(kind.equals("collection"))sql="SELECT hash FROM book_collections WHERE collection=?";else if(kind.equals("topic")||kind.equals("series"))sql="SELECT hash FROM book_meta WHERE "+kind+"=?";else return found;try(Cursor c=getReadableDatabase().rawQuery(sql,args)){while(c.moveToNext())if(c.getString(0).matches("[a-f0-9]{64}"))found.add(c.getString(0));}return found;}
 static String inHashes(Set<String> hashes){List<String> quoted=new ArrayList<>();for(String h:hashes)if(h.matches("[a-f0-9]{64}"))quoted.add("'"+h+"'");return quoted.isEmpty()?"0=1":"hash IN ("+String.join(",",quoted)+")";}
}
